import time


class Cache:
    def __init__(self, seconds):
        self.seconds = seconds
        self.entries = {}

    def put(self, key, value):
        self.entries[key] = (time.monotonic() + self.seconds, value)

    def get(self, key):
        expires, value = self.entries.get(key, (0, None))
        if time.monotonic() > expires:
            return None
        return value
